const mode = process.argv.length === 3 ? process.argv[2] : null
if (mode !== 'replay' && mode !== 'summary') fail('error: usage: cli.js replay|summary')

const NAME = /^[A-Za-z0-9_.\/:-]+$/
const INT = /^(0|[1-9][0-9]*)$/
const text = readFileSync(0, 'utf8')
const lines = text.split('\n')
if (lines[lines.length - 1] === '') lines.pop()

const policies = new Map()
const routes = new Map()
const states = new Map()
const stats = new Map()
const out = []
let seenEvent = false
let lastTick = null
let allowed = 0, denied = 0

class Err extends Error {}
const num = (s, field, least) => {
  if (!INT.test(s) || BigInt(s) < BigInt(least)) throw new Err(`${field} must be an integer of at least ${least}`)
  return BigInt(s)
}

function stateFor(p, key) {
  const id = p.name + '\0' + key
  return states.get(id)
}

function handle(t) {
  const d = t[0]
  if (d !== 'bucket' && d !== 'window' && d !== 'route' && d !== 'event') throw new Err(`unknown directive ${d}`)
  if (d !== 'event' && seenEvent) throw new Err('declarations must come before the first event')
  if (d === 'bucket') {
    if (t.length !== 5) throw new Err('expected bucket <name> <capacity> <refill> <per>')
    if (!NAME.test(t[1])) throw new Err(`invalid policy name ${t[1]}`)
    const capacity = num(t[2], 'capacity', 1), refill = num(t[3], 'refill', 0), per = num(t[4], 'per', 1)
    if (policies.has(t[1])) throw new Err(`policy ${t[1]} is declared twice`)
    policies.set(t[1], { name: t[1], kind: 'bucket', capacity, refill, per })
  } else if (d === 'window') {
    if (t.length !== 4) throw new Err('expected window <name> <limit> <span>')
    if (!NAME.test(t[1])) throw new Err(`invalid policy name ${t[1]}`)
    const limit = num(t[2], 'limit', 0), span = num(t[3], 'span', 1)
    if (policies.has(t[1])) throw new Err(`policy ${t[1]} is declared twice`)
    policies.set(t[1], { name: t[1], kind: 'window', limit, span })
  } else if (d === 'route') {
    if (t.length < 3) throw new Err('expected route <prefix> <policy>...')
    if (!NAME.test(t[1])) throw new Err(`invalid route prefix ${t[1]}`)
    if (routes.has(t[1])) throw new Err(`prefix ${t[1]} is routed twice`)
    for (const n of t.slice(2)) if (!policies.has(n)) throw new Err(`unknown policy ${n}`)
    routes.set(t[1], t.slice(2).map((n) => policies.get(n)))
  } else {
    if (t.length !== 3) throw new Err('expected event <tick> <key>')
    const tick = num(t[1], 'tick', 0)
    if (!NAME.test(t[2])) throw new Err(`invalid key ${t[2]}`)
    if (lastTick !== null && tick < lastTick) throw new Err(`tick ${tick} is before tick ${lastTick}`)
    seenEvent = true
    lastTick = tick
    event(tick, t[2])
  }
}

function event(tick, key) {
  let best = null
  for (const [pre, ps] of routes) if (key.startsWith(pre) && (best === null || pre.length > best.length)) best = pre
  let denier = null
  if (best !== null) {
    const ps = routes.get(best)
    const sts = ps.map((p) => {
      const id = p.name + '\0' + key
      let s = states.get(id)
      if (p.kind === 'bucket') {
        if (!s) { s = { T: p.capacity * p.per, last: tick }; states.set(id, s) }
        else {
          s.T += p.refill * (tick - s.last)
          s.last = tick
          const cap = p.capacity * p.per
          if (s.T > cap) s.T = cap
        }
      } else {
        if (!s) { s = { ticks: [] }; states.set(id, s) }
        const cutoff = tick - p.span
        while (s.ticks.length && s.ticks[0] <= cutoff) s.ticks.shift()
      }
      return s
    })
    for (let i = 0; i < ps.length; i++) {
      const p = ps[i], s = sts[i]
      const ok = p.kind === 'bucket' ? s.T >= p.per : BigInt(s.ticks.length) < p.limit
      if (!ok) { denier = p.name; break }
    }
    if (denier === null) {
      ps.forEach((p, i) => { if (p.kind === 'bucket') sts[i].T -= p.per; else sts[i].ticks.push(tick) })
    }
  }
  let st = stats.get(key)
  if (!st) { st = { a: 0, d: 0 }; stats.set(key, st) }
  if (denier === null) { st.a++; allowed++; out.push(`${tick} ${key} allow`) }
  else { st.d++; denied++; out.push(`${tick} ${key} deny ${denier}`) }
}

for (let i = 0; i < lines.length; i++) {
  const l = lines[i].trim()
  if (l === '' || l.startsWith('#')) continue
  try { handle(l.split(/\s+/)) } catch (e) {
    if (e instanceof Err) fail(`error: line ${i + 1}: ${e.message}`)
    throw e
  }
}

if (mode === 'replay') process.stdout.write(out.map((x) => x + '\n').join(''))
else {
  const keys = [...stats.keys()].sort((a, b) => (a < b ? -1 : a > b ? 1 : 0))
  let s = ''
  for (const k of keys) s += `${k} allowed=${stats.get(k).a} denied=${stats.get(k).d}\n`
  process.stdout.write(s + `total allowed=${allowed} denied=${denied}\n`)
}
EOF
